            var scope = r.Enter();
            while (r.NextChild(ref scope))
            {
                switch (r.LocalName)
                {
                    case "Text" when r.InNamespace(XmlNamespaces.Meteorology): text.Add(r, global::JmaXml.Meteorology.Text.Read(r)); break;
