        /// <summary>編集識別子</summary>
        /// <remarks>
        /// <para>複数の領域をまとめるときの識別として利用する</para>
        /// <list type="bullet">
        /// <item><description>0</description></item>
        /// <item><description>1</description></item>
        /// </list>
        /// </remarks>
        public string? EditingMark { get; init; }

        /// <summary>他情報参照</summary>
        /// <remarks>
        /// <para>土砂災害警戒情報などの発表状況を記載する</para>
        /// </remarks>
